-- Create database separately: CREATE DATABASE school_erp;
CREATE TABLE teacher(teacher_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,phone VARCHAR(20),qualification VARCHAR(120),hire_date DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE class(class_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,class_name VARCHAR(40) NOT NULL,section VARCHAR(10) NOT NULL,academic_year VARCHAR(9) NOT NULL,room_number VARCHAR(20),class_teacher_id BIGINT REFERENCES teacher ON DELETE SET NULL,UNIQUE(class_name,section,academic_year));
CREATE TABLE subject(subject_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,subject_name VARCHAR(100) NOT NULL,subject_code VARCHAR(20) NOT NULL UNIQUE,description TEXT);
CREATE TABLE student(student_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admission_no VARCHAR(30) NOT NULL UNIQUE,first_name VARCHAR(80) NOT NULL,last_name VARCHAR(80) NOT NULL,date_of_birth DATE NOT NULL,gender VARCHAR(20) NOT NULL CHECK(gender IN('Male','Female','Other','Prefer not to say')),email VARCHAR(255) UNIQUE,phone VARCHAR(20),address TEXT,class_id BIGINT NOT NULL REFERENCES class ON DELETE RESTRICT,admission_date DATE NOT NULL DEFAULT CURRENT_DATE,status VARCHAR(20) NOT NULL DEFAULT 'Active' CHECK(status IN('Active','Inactive','Graduated','Transferred')));
CREATE TABLE class_subject(class_subject_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,class_id BIGINT NOT NULL REFERENCES class ON DELETE CASCADE,subject_id BIGINT NOT NULL REFERENCES subject ON DELETE RESTRICT,teacher_id BIGINT NOT NULL REFERENCES teacher ON DELETE RESTRICT,academic_year VARCHAR(9) NOT NULL,UNIQUE(class_id,subject_id,academic_year));
CREATE TABLE attendance(attendance_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES student ON DELETE CASCADE,attendance_date DATE NOT NULL,status VARCHAR(12) NOT NULL CHECK(status IN('Present','Absent','Late','Excused')),remarks TEXT,marked_by BIGINT REFERENCES teacher ON DELETE SET NULL,UNIQUE(student_id,attendance_date));
CREATE TABLE exam(exam_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,exam_name VARCHAR(100) NOT NULL,exam_type VARCHAR(40) NOT NULL,class_id BIGINT NOT NULL REFERENCES class ON DELETE CASCADE,subject_id BIGINT NOT NULL REFERENCES subject ON DELETE RESTRICT,exam_date DATE NOT NULL,max_marks NUMERIC(7,2) NOT NULL CHECK(max_marks>0));
CREATE TABLE exam_result(result_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,exam_id BIGINT NOT NULL REFERENCES exam ON DELETE CASCADE,student_id BIGINT NOT NULL REFERENCES student ON DELETE CASCADE,marks_obtained NUMERIC(7,2) NOT NULL CHECK(marks_obtained>=0),remarks TEXT,UNIQUE(exam_id,student_id));
CREATE TABLE fee_payment(payment_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES student ON DELETE RESTRICT,amount NUMERIC(10,2) NOT NULL CHECK(amount>0),payment_date DATE NOT NULL DEFAULT CURRENT_DATE,payment_mode VARCHAR(20) NOT NULL CHECK(payment_mode IN('Cash','Card','UPI','Bank Transfer','Cheque')),payment_status VARCHAR(20) NOT NULL DEFAULT 'Pending' CHECK(payment_status IN('Pending','Paid','Failed','Refunded')),transaction_ref VARCHAR(100) UNIQUE,fee_type VARCHAR(50) NOT NULL);
CREATE TABLE notice(notice_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,category VARCHAR(50) NOT NULL,published_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT REFERENCES teacher ON DELETE SET NULL);
CREATE TABLE app_user(user_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('admin','teacher','student')),student_id BIGINT UNIQUE REFERENCES student ON DELETE CASCADE,teacher_id BIGINT UNIQUE REFERENCES teacher ON DELETE CASCADE,CHECK((role='student' AND student_id IS NOT NULL AND teacher_id IS NULL) OR (role='teacher' AND teacher_id IS NOT NULL AND student_id IS NULL) OR (role='admin' AND student_id IS NULL AND teacher_id IS NULL)));
CREATE INDEX idx_student_class ON student(class_id); CREATE INDEX idx_attendance_date ON attendance(attendance_date); CREATE INDEX idx_exam_class_date ON exam(class_id,exam_date); CREATE INDEX idx_result_student ON exam_result(student_id); CREATE INDEX idx_fee_student ON fee_payment(student_id,payment_date DESC); CREATE INDEX idx_notice_active ON notice(is_active,published_at DESC);